,\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/14/7/\",\"title\":\"TEXT 7\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":3857,\"bb\":568384,\"url_path\":\"/en/library/bg/14/6/devanagari/\",\"body_final\":\"तत्र सत्त्वं निर्मलत्वात्प्रकाशकमनामयम् ।
सुखसङ्गेन बध्‍नाति ज्ञानसङ्गेन चानघ ॥ ६ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3858,\"bb\":3396,\"url_path\":\"/en/library/bg/14/6/b3396/\",\"body_value\":\"tatra sattvaṁ nirmalatvāt
prakāśakam anāmayam
sukha-saṅgena badhnāti
jñāna-saṅgena cānagha\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3859,\"bb\":3397,\"url_path\":\"/en/library/bg/14/6/b3397/\",\"shadow_value\":\"tatra – there; sattvam – the mode of goodness; nirmalatvāt – being purest in the material world; prakāśakam – illuminating; anāmayam – without any sinful reaction; sukha – with happiness; saṅgena – by association; badhnāti – conditions; jñāna – with knowledge; saṅgena – by association; ca – also; anagha – O sinless one.\",\"word_for_word_value\":[{\"word\":\"tatra\",\"translation\":\"there\"},{\"word\":\"sattvam\",\"translation\":\"the mode of goodness\"},{\"word\":\"nirmalatvāt\",\"translation\":\"being purest in the material world\"},{\"word\":\"prakāśakam\",\"translation\":\"illuminating\"},{\"word\":\"anāmayam\",\"translation\":\"without any sinful reaction\"},{\"word\":\"sukha\",\"translation\":\"with happiness\"},{\"word\":\"saṅgena\",\"translation\":\"by association\"},{\"word\":\"badhnāti\",\"translation\":\"conditions\"},{\"word\":\"jñāna\",\"translation\":\"with knowledge\"},{\"word\":\"saṅgena\",\"translation\":\"by association\"},{\"word\":\"ca\",\"translation\":\"also\"},{\"word\":\"anagha\",\"translation\":\"O sinless one\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3860,\"bb\":3398,\"url_path\":\"/en/library/bg/14/6/b3398/\",\"body_value\":\"O sinless one, the mode of goodness, being purer than the others, is illuminating, and it frees one from all sinful reactions. Those situated in that mode become conditioned by a sense of happiness and knowledge.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3861,\"bb\":3399,\"url_path\":\"/en/library/bg/14/6/b3399/\",\"body_value\":\"The living entities conditioned by material nature are of various types. One is happy, another is very active, and another is helpless. All these types of psychological manifestations are causes of the entities’ conditioned status in nature. How they are differently conditioned is explained in this section of Bhagavad-gītā. The mode of goodness is first considered. The effect of developing the mode of goodness in the material world is that one becomes wiser than those otherwise conditioned. A man in the mode of goodness is not so much affected by material miseries, and he has a sense of advancement in material knowledge. The representative type is the brāhmaṇa, who is supposed to be situated in the mode of goodness. This sense of happiness is due to understanding that, in the mode of goodness, one is more or less free from sinful reactions. Actually, in the Vedic literature it is said that the mode of goodness means greater knowledge and a greater sense of happiness.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3862,\"bb\":3400,\"url_path\":\"/en/library/bg/14/6/b3400/\",\"body_value\":\"$25\"}]}],\"short_title\":\"Bg. 14.6\",\"medium_title\":\"Bhagavad-gītā As It Is 14.6\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-z